const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    // demo: 10 per minute tick with 1 s gaps (~45 s per run, so runs never overlap); real: 5 per 15-min tick, 60–180 s apart
    maxSendsPerRun: demoMode ? 10 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const M = {};
M.guard = (function () {
  const module = { exports: {} };
/**
 * guard.js – the safety guard that runs right before every email-sending node.
 * - Blocks the run (throws) if any recipient is not on TEST_RECIPIENT_ALLOWLIST.
 * - An empty allowlist blocks everything in test mode.
 * - DEMO_MODE: rewrites To to TEST_PROSPECT_EMAIL (internal notifications: to SENDER_EMAIL), drops Cc/Bcc and marks
 *   the message as a test with the header X-Nexsale-Test (no visible [TEST] in the subject – user's decision 2026-11-15).
 * - Real mode (DEMO_MODE=false) additionally needs ALLOW_REAL_SENDING=true, otherwise it blocks.
 */
class GuardError extends Error {
  constructor(message, details) {
    super(message);
    this.name = 'GuardError';
    this.details = details || {};
  }
}

function norm(e) {
  return String(e || '').trim().toLowerCase();
}

function splitAddresses(v) {
  if (!v) return [];
  const list = Array.isArray(v) ? v : String(v).split(/[,;]/);
  return list
    .map((x) => {
      const m = String(x).match(/<([^>]+)>/);
      return norm(m ? m[1] : x);
    })
    .filter(Boolean);
}

const INTERNAL_PURPOSES = ['internal', 'report'];

function guardEmail(msg, cfg) {
  if (!msg || typeof msg !== 'object') throw new GuardError('Guard: no message');
  if (!cfg || typeof cfg !== 'object') throw new GuardError('Guard: no config');
  const original = { to: splitAddresses(msg.to), cc: splitAddresses(msg.cc), bcc: splitAddresses(msg.bcc) };
  if (!original.to.length) throw new GuardError('Guard: message has no recipient');
  const out = Object.assign({}, msg);
  if (cfg.demoMode) {
    if (!cfg.testProspectEmail) throw new GuardError('Guard: DEMO_MODE is on but TEST_PROSPECT_EMAIL is empty');
    // internal notifications (Campaign ready, weekly report) inform the team only – never the test prospect inbox
    const internal = INTERNAL_PURPOSES.includes(String(msg.purpose || ''));
    out.to = internal && cfg.senderEmail ? cfg.senderEmail : cfg.testProspectEmail;
    out.cc = '';
    out.bcc = '';
    out.subject = String(msg.subject || '').replace(/^\s*\[TEST\]\s*/, '');
    out.testMarker = true; // becomes the header X-Nexsale-Test: true
    out.original_to = original.to.join(', ');
  } else if (!cfg.allowRealSending) {
    throw new GuardError('Guard: DEMO_MODE is off but ALLOW_REAL_SENDING is not true – blocked', { to: original.to });
  }
  const allow = (cfg.allowlist || []).map(norm);
  const finalRecipients = [].concat(splitAddresses(out.to), splitAddresses(out.cc), splitAddresses(out.bcc));
  if (cfg.demoMode || allow.length) {
    if (!allow.length) throw new GuardError('Guard: TEST_RECIPIENT_ALLOWLIST is empty – every send is blocked');
    const bad = finalRecipients.filter((r) => !allow.includes(r));
    if (bad.length) throw new GuardError('Guard: recipient not on allowlist: ' + bad.join(', '), { blocked: bad });
  }
  out.guard = { passed: true, demoMode: !!cfg.demoMode, recipients: finalRecipients, checkedAt: new Date().toISOString() };
  return out;
}

/** Blocklist check: entries are {value} (email or domain) or plain strings. */
function isBlocked(email, blocklist) {
  const e = norm(email);
  if (!e) return false;
  const domain = e.split('@')[1] || '';
  return (blocklist || []).some((entry) => {
    const v = norm(typeof entry === 'string' ? entry : entry && (entry.value || entry.email || entry.domain));
    if (!v) return false;
    if (v.includes('@')) return v === e;
    return v === domain || domain.endsWith('.' + v);
  });
}

const guardApi = { GuardError, guardEmail, isBlocked, splitAddresses, INTERNAL_PURPOSES };
if (typeof module !== 'undefined' && module.exports) module.exports = guardApi;

  return module.exports;
})();

M.mime = (function () {
  const module = { exports: {} };
/**
 * mime.js – builds the base64url RFC 822 message for the Gmail API messages.send call.
 * Threading: In-Reply-To/References headers plus the Gmail threadId keep steps 2–4 in one thread.
 */
function encodeHeader(v) {
  const s = String(v || '');
  // eslint-disable-next-line no-control-regex
  if (/^[\x00-\x7F]*$/.test(s)) return s;
  return '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
}

function base64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function wrap76(b64) {
  return b64.replace(/(.{76})/g, '$1\r\n');
}

function buildRawEmail(m) {
  if (!m || !m.to) throw new Error('buildRawEmail: "to" is required');
  const headers = [
    'From: ' + (m.fromName ? `${encodeHeader(m.fromName)} <${m.from}>` : m.from || ''),
    'To: ' + m.to,
    'Subject: ' + encodeHeader(m.subject || ''),
    'MIME-Version: 1.0',
  ];
  if (m.inReplyTo) {
    headers.push('In-Reply-To: ' + m.inReplyTo);
    headers.push('References: ' + (m.references || m.inReplyTo));
  }
  if (m.listUnsubscribe) headers.push('List-Unsubscribe: ' + m.listUnsubscribe);
  Object.entries(m.extraHeaders || {}).forEach(([k, v]) => {
    if (/^X-[A-Za-z-]+$/.test(k)) headers.push(k + ': ' + String(v).replace(/[\r\n]/g, ' '));
  });
  const part = (type, text) => 'Content-Type: ' + type + '; charset="UTF-8"\r\nContent-Transfer-Encoding: base64\r\n\r\n' + wrap76(Buffer.from(String(text || ''), 'utf8').toString('base64'));
  let raw;
  if (m.html) {
    // plain text + HTML alternative (internal notifications); prospect emails stay plain text (deliverability)
    const boundary = 'nxs-' + Buffer.from(String(m.subject || '') + String(m.to)).toString('hex').slice(0, 24);
    headers.push('Content-Type: multipart/alternative; boundary="' + boundary + '"');
    raw = headers.join('\r\n') + '\r\n\r\n--' + boundary + '\r\n' + part('text/plain', m.body) + '\r\n--' + boundary + '\r\n' + part('text/html', m.html) + '\r\n--' + boundary + '--';
  } else {
    headers.push('Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64');
    raw = headers.join('\r\n') + '\r\n\r\n' + wrap76(Buffer.from(String(m.body || ''), 'utf8').toString('base64'));
  }
  return base64url(raw);
}

function decodeRawEmail(raw) {
  const s = Buffer.from(String(raw).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
  const [head, ...rest] = s.split('\r\n\r\n');
  const headers = {};
  head.split('\r\n').forEach((l) => {
    const i = l.indexOf(':');
    if (i > 0) headers[l.slice(0, i).toLowerCase()] = l.slice(i + 1).trim();
  });
  const decodeWord = (v) => String(v || '').replace(/=\?UTF-8\?B\?([^?]+)\?=/g, (m, b) => Buffer.from(b, 'base64').toString('utf8'));
  const b64 = (x) => Buffer.from(String(x || '').replace(/\r\n/g, ''), 'base64').toString('utf8');
  const out = { headers, subject: decodeWord(headers.subject), to: headers.to, body: '', html: '' };
  const bm = String(headers['content-type'] || '').match(/boundary="([^"]+)"/);
  if (bm) {
    s.split('--' + bm[1]).forEach((p) => {
      const [ph, ...pb] = p.replace(/^\r\n/, '').split('\r\n\r\n');
      if (/text\/plain/.test(ph)) out.body = b64(pb.join('\r\n\r\n').replace(/\r\n--$/, ''));
      if (/text\/html/.test(ph)) out.html = b64(pb.join('\r\n\r\n').replace(/\r\n--$/, ''));
    });
  } else {
    out.body = b64(rest.join('\r\n\r\n'));
  }
  return out;
}

const mimeApi = { encodeHeader, base64url, buildRawEmail, decodeRawEmail };
if (typeof module !== 'undefined' && module.exports) module.exports = mimeApi;

  return module.exports;
})();

M.airtable = (function () {
  const module = { exports: {} };
/**
 * airtable.js – helpers for the Airtable REST API: batches of 10, formula building,
 * flattening records. Free-plan friendly (CLAUDE.md: batches of 10 per call).
 */
const BATCH = 10;

function chunk(list, size) {
  const n = size || BATCH;
  const out = [];
  for (let i = 0; i < (list || []).length; i += n) out.push(list.slice(i, i + n));
  return out;
}

function clean(fields) {
  const out = {};
  Object.keys(fields || {}).forEach((k) => {
    if (fields[k] !== undefined) out[k] = fields[k];
  });
  return out;
}

/** -> [{records:[{fields}]}] one item per HTTP call */
function createBatches(fieldsList) {
  return chunk((fieldsList || []).map((f) => ({ fields: clean(f) }))).map((records) => ({ records, typecast: true }));
}

/** updates: [{id, fields}] -> [{records:[{id, fields}]}] */
function updateBatches(updates) {
  return chunk((updates || []).filter((u) => u && u.id).map((u) => ({ id: u.id, fields: clean(u.fields) }))).map((records) => ({ records, typecast: true }));
}

function esc(v) {
  return String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function eq(field, value) {
  if (typeof value === 'number' || typeof value === 'boolean') return `{${field}}=${value === true ? 'TRUE()' : value === false ? 'FALSE()' : value}`;
  return `{${field}}='${esc(value)}'`;
}

function and(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `AND(${p.join(',')})`;
}

function or(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `OR(${p.join(',')})`;
}

/** Airtable record -> flat object with id */
function flat(record) {
  if (!record) return null;
  return Object.assign({ id: record.id, createdTime: record.createdTime }, record.fields || {});
}

function flatList(response) {
  return ((response && response.records) || []).map(flat);
}

/** n8n items from a (paginated) list node -> flat records */
function fromItems(items) {
  // With pagination on, n8n's HTTP node retries and then passes the error body on instead of failing.
  // A failed read must never look like an empty table (e.g. an "empty" Blocklist), so fail here.
  (items || []).forEach((i) => {
    const e = i && i.json && i.json.error;
    if (e) throw new Error('Airtable read failed after retries: ' + (typeof e === 'string' ? e : e.message || e.type || JSON.stringify(e)).slice(0, 200));
  });
  return flatList({ records: (items || []).flatMap((i) => (i && i.json && i.json.records) || []) });
}

/** OR() over ids for a text field, e.g. lead_record_id */
function inIds(field, ids) {
  const list = Array.from(new Set((ids || []).filter(Boolean)));
  if (!list.length) return "{" + field + "}='__none__'";
  return or(...list.map((id) => eq(field, id)));
}

const airtableApi = { fromItems, inIds, BATCH, chunk, createBatches, updateBatches, eq, and, or, esc, flat, flatList, clean };
if (typeof module !== 'undefined' && module.exports) module.exports = airtableApi;

  return module.exports;
})();

// ---- node logic ----
const cfg = $('Config').first().json.cfg;
const blocklist = M.airtable.fromItems($('Load Blocklist').all()); // throws if the Blocklist could not be read
// placeholder items from callers without work ({} or {skip:true}) are dropped here
const msgs = $('When called').all().map((i) => i.json).filter((m) => m && m.ref && !m.skip);
const out = [];
for (const m of msgs) {
  const originals = M.guard.splitAddresses(m.to);
  const hit = originals.find((a) => M.guard.isBlocked(a, blocklist));
  if (hit) throw new M.guard.GuardError('Guard: recipient ' + hit + ' is on the Blocklist (ref ' + m.ref + ')');
  const g = M.guard.guardEmail(m, cfg); // throws -> run stops -> error handler alerts Slack
  const raw = M.mime.buildRawEmail({ from: cfg.senderEmail, fromName: m.fromName, to: g.to, subject: g.subject, body: m.body, html: m.html, inReplyTo: m.inReplyTo,
    extraHeaders: g.testMarker ? { 'X-Nexsale-Test': 'true' } : {}, listUnsubscribe: cfg.senderEmail ? '<mailto:' + cfg.senderEmail + '?subject=STOP>' : '' });
  const body = { raw };
  if (m.threadId) body.threadId = m.threadId;
  out.push({ json: { ref: m.ref, gmail: body, sent_to: g.to, original_to: g.original_to || g.to, subject: g.subject, purpose: m.purpose || 'outreach' } });
}
return out;

const guarded = $('Guard: allowlist + blocklist').all();
return $input.all().map((it, i) => ({ json: {
  ref: guarded[i].json.ref, ok: !!it.json.id, id: it.json.id, threadId: it.json.threadId,
  sent_to: guarded[i].json.sent_to, original_to: guarded[i].json.original_to, subject: guarded[i].json.subject, sent_at: new Date().toISOString(),
} }));
